def count_odd_f(limit=100):
    N = 0
    for S in range(2 * limit - 1):
        # Determine required parities based on S mod 4
        S_mod_4 = S % 4

        if S_mod_4 == 0:
            P_x, P_y = 1, 1  # Odd, Odd
        elif S_mod_4 == 1:
            P_x, P_y = 0, 1  # Even, Odd
        elif S_mod_4 == 2:
            P_x, P_y = 0, 0  # Even, Even
        elif S_mod_4 == 3:
            P_x, P_y = 1, 0  # Odd, Even
        else:
            continue

        # Count pairs (x, y) such that x+y=S and 0 <= x, y < limit
        count_S = 0
        for x in range(limit):
            y = S - x

            if 0 <= y < limit:
                if x % 2 == P_x and y % 2 == P_y:
                    count_S += 1

        N += count_S
    return N

